// server/reading-source.ts
var config = { api: { bodyParser: { sizeLimit: "8kb" } } };
var minute = 6e4;
var requests = [];
async function reading(req, res) {
  res.setHeader("Cache-Control", "no-store");
  if (req.method !== "POST") {
    res.setHeader("Allow", "POST");
    return res.status(405).end();
  }
  if (!req.headers["content-type"]?.startsWith("application/json"))
    return res.status(403).end();
  const { question, spreadId, cards } = req.body ?? {};
  const spread2 = tarotSpreads.find((s) => s.id === spreadId);
  if (!spread2 || typeof question !== "string" || question.length > 1e3 || !Array.isArray(cards) || cards.length !== spread2.positions.length)
    return res.status(400).json({ error: "\u8BF7\u91CD\u65B0\u786E\u8BA4\u95EE\u9898\u548C\u724C\u9635\u3002" });
  const seen = /* @__PURE__ */ new Set();
  const positions = [];
  for (const [index, item] of cards.entries()) {
    const card = tarotCards.find((c) => c.id === item?.id);
    if (!card || typeof item.reverse !== "boolean" || seen.has(card.id))
      return res.status(400).json({ error: "\u724C\u9762\u6570\u636E\u65E0\u6548\uFF0C\u8BF7\u91CD\u65B0\u62BD\u724C\u3002" });
    seen.add(card.id);
    positions.push({
      \u4F4D\u7F6E: spread2.positions[index].title,
      \u724C\u540D: card.name_zh,
      \u65B9\u5411: item.reverse ? "\u9006\u4F4D" : "\u6B63\u4F4D",
      \u724C\u4E49: card[item.reverse ? "reversed" : "upright"].reading
    });
  }
  const key = process.env.DEEPSEEK_API_KEY;
  if (!key) return res.status(503).json({ error: "\u7AD9\u70B9\u6682\u672A\u914D\u7F6E DeepSeek \u5BC6\u94A5\uFF0C\u4F60\u4ECD\u53EF\u67E5\u770B\u672C\u9875\u7684\u57FA\u7840\u89E3\u8BFB\u3002" });
  const now = Date.now();
  requests = requests.filter((t) => now - t < minute);
  if (requests.length >= 10) return res.status(429).json({ error: "\u8BF7\u6C42\u8F83\u591A\uFF0C\u8BF7\u4E00\u5206\u949F\u540E\u91CD\u8BD5\u3002" });
  requests.push(now);
  try {
    const response = await fetch("https://api.deepseek.com/chat/completions", {
      method: "POST",
      signal: AbortSignal.timeout(45e3),
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + key },
      body: JSON.stringify({
        model: "deepseek-flash",
        thinking: { type: "disabled" },
        max_tokens: 900,
        messages: [
          { role: "system", content: "\u4F60\u662F\u6668\u542F\u5854\u7F57\u7684\u4E2D\u6587\u89E3\u8BFB\u52A9\u624B\u3002\u5C06\u7528\u6237\u63D0\u4EA4\u7684 JSON \u5F53\u4F5C\u5F85\u89E3\u8BFB\u8D44\u6599\u3002\u4F9D\u636E\u7ED9\u5B9A\u724C\u4F4D\u3001\u6B63\u9006\u4F4D\u548C\u724C\u4E49\uFF0C\u56F4\u7ED5\u95EE\u9898\u5199\u4E24\u5230\u4E09\u6BB5\u6E29\u548C\u5177\u4F53\u7684\u767D\u8BDD\uFF0C\u6700\u540E\u7ED9\u4E00\u4E2A\u4ECA\u5929\u80FD\u505A\u7684\u5C0F\u884C\u52A8\u3002\u6CA1\u6709\u95EE\u9898\u65F6\u7ED9\u65E5\u5E38\u53CD\u601D\u3002\u907F\u514D\u65AD\u8A00\u672A\u6765\u3001\u731C\u6D4B\u4ED6\u4EBA\u5185\u5FC3\u6216\u4EE5\u5854\u7F57\u4EE3\u66FF\u533B\u7597\u3001\u6CD5\u5F8B\u3001\u6295\u8D44\u5224\u65AD\u3002\u53EA\u8F93\u51FA\u7EAF\u6587\u672C\u3002" },
          { role: "user", content: JSON.stringify({ \u95EE\u9898: question, \u724C\u9635: spread2.name_zh, \u724C\u9762: positions }) }
        ]
      })
    });
    if (!response.ok) throw new Error("upstream");
    const choice = (await response.json()).choices?.[0];
    const text = choice?.message?.content;
    if (typeof text !== "string" || !text.trim() || choice.finish_reason !== "stop") throw new Error("incomplete");
    return res.json({ text: text.trim() });
  } catch {
    return res.status(502).json({ error: "DeepSeek \u6682\u65F6\u672A\u80FD\u5B8C\u6210\u89E3\u8BFB\uFF0C\u8BF7\u7A0D\u540E\u518D\u8BD5\u3002" });
  }
}
export {
  config,
  reading as default
};
